// Shared school application. All account data and assessed scores come from the API.
const APP={user:null,content:[],classes:[],results:[],level:'core',request:0,videoPassed:0};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subjectName=id=>D.find(x=>x.id===id)?.en||id;
const staffUser=()=>['teacher','admin'].includes(APP.user?.role);
async function call(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-Learning-Universe':'1'},body:body===undefined?undefined:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed.');return j}
const handle=fn=>async(...args)=>{try{await fn(...args)}catch(e){toast(e.message)}};
function button(t,fn,secondary=false){const b=el('button','btn'+(secondary?' o':''),t);b.type='button';b.onclick=handle(fn);return b}
function empty(t){return el('div','empty',t)}
function modal(title,wide=false){const w=el('div');w.append(el('h2',null,title));w.firstChild.id='mt';openOv(w);$('ov').querySelector('.sheet').classList.toggle('wide',wide);return w}
function providerLogo(url,title){let domain;try{domain=new URL(url).hostname}catch{return null}const i=el('img','providerLogo');i.alt=title+' official site icon';i.loading='lazy';i.referrerPolicy='no-referrer';i.src='https://'+domain+'/favicon.ico';i.onerror=()=>{i.replaceWith(el('span','pill',title.slice(0,2).toUpperCase()))};return i}
function logoCards(root){const cards=[];if(root.matches?.('a.lk,a.act'))cards.push(root);cards.push(...root.querySelectorAll?.('a.lk,a.act')||[]);cards.forEach(a=>{if(a.dataset.logo||!/^https:\/\//.test(a.href))return;a.dataset.logo='1';const img=providerLogo(a.href,a.querySelector('b')?.textContent||new URL(a.href).hostname);if(img)a.prepend(img)})}
function card(c){const a=el('article','appcard'+(c.recommended?' recommended':''));const top=el('div','row');if(c.url){const i=providerLogo(c.url,c.title);if(i)top.append(i)}top.append(el('span','pill',c.kind+' · Grade '+c.grade),el('span','pill',c.difficulty));a.append(top,el('h3',null,c.title),el('p',null,c.description));if(c.recommended)a.append(el('span','pill','✦ Recommended for you'));if(c.deadline)a.append(el('small','mut','Due '+new Date(c.deadline).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'})+' (KSA)'));const row=el('div','row');if(c.url){const l=el('a','btn o',c.kind==='video'?'▶ Watch video':'Open resource ↗');l.href=c.url;l.target='_blank';l.rel='noopener noreferrer';row.append(l)}if(c.questions?.length)row.append(button(c.kind==='video'?'Answer follow-up':'Start assessment',()=>assess(c)));if(staffUser()&&c.editable)row.append(button('Edit',async()=>{const r=await call('/api/content/edit?id='+encodeURIComponent(c.id));await editor(r.content)},true));a.append(row);return a}
function query(){const p=new URLSearchParams({grade:$('gradeFilter').value,subject:$('subjectFilter').value});if($('classFilter').value)p.set('class',$('classFilter').value);return p}
async function renderLearning(){const n=++APP.request;const r=await call('/api/content?'+query());if(n!==APP.request)return;APP.content=r.content;APP.level=r.level;$('personalLevel').textContent=r.level.charAt(0).toUpperCase()+r.level.slice(1);$('recommendation').textContent=r.reason;const tasks=APP.content.filter(c=>c.kind==='quiz'||c.kind==='mission').sort((a,b)=>Number(b.recommended)-Number(a.recommended));$('learningCards').replaceChildren(...tasks.slice(0,6).map(card));if(!tasks.length)$('learningCards').append(empty('No assessments match these filters yet.'));const vs=APP.content.filter(c=>c.kind==='video');$('videoCards').replaceChildren(...vs.map(card));if(!vs.length)$('videoCards').append(empty('Your teachers have not assigned a specific video to this grade and subject yet.'));const labs=APP.content.filter(c=>c.id.startsWith('lab-'));$('labCards').replaceChildren(...labs.map(card));if(!labs.length)$('labCards').append(empty('Choose Science, Physics, Chemistry or All subjects for virtual labs.'));renderResultCards();await renderAwards();}
function showSubject(id,tab){const w=modal(D.find(s=>s.id===id)?.e+' '+subjectName(id),true);const tabs=el('div','row appnav');tabs.append(button('🌐 Resources',()=>draw(false),true),button('🎯 Challenges',()=>draw(true),true));w.append(el('p','mut','Grade '+$('gradeFilter').value+' · '+APP.level+' pathway'),tabs);const g=el('div','links');w.append(g);function draw(ch){const cs=APP.content.filter(c=>c.subject===id&&(ch?['quiz','mission','video'].includes(c.kind):c.kind==='resource'));g.replaceChildren(...cs.map(card));if(!cs.length)g.append(empty('No content for these filters. Change the grade/subject or ask your teacher to assign content.'))}draw(tab==='q')}
async function assess(c){if(!APP.user){openGate('login');return}const w=modal(c.title,true);w.append(el('p','mut','Answer every question. Results are marked and saved by the school server.'));if(c.url){const l=el('a','btn o','Open '+(c.kind==='video'?'selected video':'task resource')+' ↗');l.href=c.url;l.target='_blank';l.rel='noopener noreferrer';w.append(l)}const form=el('form','appform');const err=el('p','errorBox');c.questions.forEach((q,i)=>{const box=el('fieldset','questionBox');box.append(el('legend',null,(i+1)+'. '+q.text));q.options.forEach((o,k)=>{const label=el('label','answerOption'),radio=el('input');radio.type='radio';radio.name='answer'+i;radio.value=k;radio.required=true;label.append(radio,el('span',null,o));box.append(label)});form.append(box)});const submit=el('button','btn','Submit answers');submit.type='submit';form.append(submit,err);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const answers=c.questions.map((_,i)=>Number(form.querySelector('input[name="answer'+i+'"]:checked').value));const r=await call('/api/submit?grade='+c.grade,{id:c.id,answers});w.replaceChildren(el('h2',null,'🎯 '+r.result.score+' / '+r.result.total+' · '+Math.round(r.result.score/r.result.total*100)+'%'),el('p','mut',r.message));w.firstChild.id='mt';r.result.feedback.forEach(f=>{const box=el('div','questionBox');box.append(el('b',null,(f.correct?'✅ ':'↻ ')+f.text),el('p','mut','Your answer: '+f.selected),el('p',null,'Correct answer: '+f.answer),el('small','mut',f.explanation));w.append(box)});w.append(button('My quiz results',()=>resultsTool()));await refreshProgress();await renderLearning();boom()}catch(e){err.textContent=e.message;submit.disabled=false}};w.append(form)}
async function refreshProgress(){if(!APP.user){APP.results=[];$('completedCount').textContent='—';$('personalScore').textContent='—';return}const r=await call('/api/results');APP.results=r.results;P={...P,...r.progress};APP.videoPassed=APP.results.filter(x=>x.kind==='video'&&x.score/x.total>=.6).length;const best={};APP.results.forEach(x=>{if(!best[x.content_id]||x.score/x.total>best[x.content_id].score/best[x.content_id].total)best[x.content_id]=x});const vals=Object.values(best);$('completedCount').textContent=r.completed;$('personalScore').textContent=vals.length?Math.round(vals.reduce((n,x)=>n+x.score/x.total,0)/vals.length*100)+'%':'—';hud();renderResultCards()}
function renderResultCards(){const g=$('resultCards');g.replaceChildren();if(!APP.user){g.append(empty('Sign in to view your private quiz results and progress.'));return}const sj=$('subjectFilter').value,gr=Number($('gradeFilter').value);const rs=APP.results.filter(r=>r.grade===gr&&(sj==='all'||r.subject===sj));rs.slice(0,4).forEach(r=>{const c=el('div','scoreBadge');c.append(el('span','pill',subjectName(r.subject)),el('b',null,r.score+' / '+r.total+' · '+Math.round(r.score/r.total*100)+'%'),el('span',null,r.title),el('small','mut',new Date(r.created).toLocaleString()),button('Review answers',()=>review(r),true));g.append(c)});if(!rs.length)g.append(empty('No results for these filters yet. Complete your first challenge.'))}
function review(r){const w=modal('📊 '+r.title,true);w.append(el('p','mut','Grade '+r.grade+' · '+r.score+' / '+r.total+' · '+new Date(r.created).toLocaleString()));r.feedback.forEach(f=>{const b=el('div','questionBox');b.append(el('b',null,(f.correct?'✅ ':'↻ ')+f.text),el('p',null,'Your answer: '+f.selected),el('p',null,'Correct answer: '+f.answer),el('p','mut',f.explanation));w.append(b)})}
function resultsTool(){if(!APP.user)return openGate('login');const w=modal('📊 My quiz results',true);const g=el('div','appgrid');APP.results.forEach(r=>{const c=el('div','scoreBadge');c.append(el('b',null,r.title),el('span',null,r.score+'/'+r.total+' · Grade '+r.grade),el('small','mut',subjectName(r.subject)+' · '+new Date(r.created).toLocaleString()),button('Review',()=>review(r),true));g.append(c)});w.append(g);if(!APP.results.length)w.append(empty('Complete an assessed challenge to see your result here.'))}
const gate=$('gate');
function closeGate(){gate.classList.add('out');document.querySelectorAll('header,main,footer,#dock').forEach(n=>n.inert=false);document.body.style.overflow='';setTimeout(()=>{if(gate.classList.contains('out'))gate.style.display='none'},500)}
function openGate(mode='login'){closeOv();gate.style.display='';gate.classList.remove('out');document.querySelectorAll('header,main,footer,#dock').forEach(n=>n.inert=true);document.body.style.overflow='hidden';$('gmain').hidden=false;$('gback').hidden=true;authForm(mode)}
let loginPortal='student';
