 const reg=mode==='register',recover=mode==='recover',teacher=!reg&&!recover&&loginPortal==='teacher';
 $('gtrack').innerHTML='<div class="auth"><div class="kick">YOUR LEARNING PASSPORT</div><h2 class="ah">'+(reg?'Create your student account':recover?'Recover your account':'Welcome, explorer')+'</h2><p class="as">Separate student and approved teacher access. No email required.</p><div class="row" id="portalTabs"></div><div class="row" id="authTabs"></div><form class="af" id="schoolAuth">'+(teacher?'<label>Employee number<input class="field" name="employeeNumber" inputmode="numeric" pattern="[0-9]{1,20}" maxlength="20" autocomplete="off" required></label>':'')+'<label>Username<input class="field" name="username" autocomplete="username" pattern="[A-Za-z0-9._-]{3,20}" required maxlength="20"></label>'+(reg?'<label>Display name<input class="field" name="name" maxlength="50" required></label><label>Your grade<select class="field" name="grade">'+Array.from({length:9},(_,i)=>'<option value="'+(i+4)+'">Grade '+(i+4)+'</option>').join('')+'</select></label>':'')+(recover?'<label>Recovery code<input class="field" name="code" required autocomplete="off"></label>':'')+'<label>'+(recover?'New password':'Password')+'<input class="field" type="password" name="password" autocomplete="'+(reg||recover?'new-password':'current-password')+'" required minlength="10" maxlength="128"></label><button class="gbtn" type="submit">'+(reg?'Create student account 🚀':recover?'Reset password':teacher?'Sign in as Teacher 👨‍🏫':'Sign in as Student 🎓')+'</button><p class="errorBox" id="authFeedback" role="alert"></p></form><p class="mut">'+(teacher?'Teacher accounts must be approved by the school administrator.':recover?'Lost your recovery code? Ask your teacher or school administrator.':'Passwords need at least 10 characters. Keep your recovery code private.')+'</p><div class="row" id="authExtra"></div></div>';
 $('portalTabs').append(button('🎓 Student sign in',()=>{loginPortal='student';authForm('login')},loginPortal!=='student'),button('👨‍🏫 Teacher sign in',()=>{loginPortal='teacher';authForm('login')},loginPortal!=='teacher'));
