async function usersTool(){
 if(APP.user?.role!=='admin')return toast('Administrator access required.');
 const w=modal('👥 Users & access',true);
 w.append(el('p','mut','Search school accounts, approve verified teachers, and reset passwords securely. Existing passwords are never shown.'));
 const users=(await call('/api/admin/users')).users;
 const controls=el('div','lu-userfilters');
 const search=el('input','field');search.type='search';search.placeholder='Search name, username or employee number';search.setAttribute('aria-label','Search users');
 const select=el('select','field');select.setAttribute('aria-label','Filter by account role');
 [['all','All users'],['teacher','Teachers'],['student','Students'],['admin','Administrators']].forEach(([v,l])=>select.append(new Option(l,v)));
 const count=el('span','pill','');
 controls.append(search,select,count);w.append(controls);
 const area=el('div','lu-userlist');w.append(area);
 const refresh=async()=>{const data=(await call('/api/admin/users')).users;users.splice(0,users.length,...data);render()};
 const showReset=u=>{
  if(u.role==='admin')return;
  const form=el('form','appform');
  form.innerHTML='<h3>Reset account password</h3><p class="mut">Set a new temporary password for @'+esc(u.username)+'. All active sessions for this account will be signed out. Give the new password and recovery code to the account owner privately.</p><label>New temporary password<input class="field" name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required></label><div class="row"><button class="btn" type="submit">Reset password</button><button type="button" class="btn o" id="cancelReset">Cancel</button></div><p class="errorBox" role="alert"></p>';
  area.replaceChildren(form);form.querySelector('#cancelReset').onclick=render;
  form.onsubmit=async e=>{e.preventDefault();if(!confirm('Reset the password for @'+u.username+'?'))return;const b=form.querySelector('button[type="submit"]');b.disabled=true;try{const r=await call('/api/admin/reset-password',{id:u.id,password:form.elements.password.value});form.replaceChildren(el('h3',null,'Password reset successfully'),el('p','mut','Share the temporary password you chose and the recovery code below privately. The code is only shown once.'),el('div','recovery',r.recoveryCode),button('Copy recovery code',()=>navigator.clipboard?.writeText(r.recoveryCode),true),button('Back to users',refresh,true))}catch(err){form.querySelector('.errorBox').textContent=err.message;b.disabled=false}};
 };
 const editEmployee=u=>{
  const form=el('form','appform');
  form.innerHTML='<h3>Verify employee number</h3><p class="mut">Enter the confirmed employee number for @'+esc(u.username)+' before approving teacher access.</p><label>Verified employee number<input class="field" name="employeeNumber" inputmode="numeric" pattern="[0-9]{1,20}" maxlength="20" required></label><div class="row"><button class="btn" type="submit">Save employee number</button><button class="btn o" type="button" id="cancelNumber">Cancel</button></div><p class="errorBox" role="alert"></p>';
  form.elements.employeeNumber.value=u.employeeNumber||'';area.replaceChildren(form);
  form.querySelector('#cancelNumber').onclick=render;
  form.onsubmit=async e=>{e.preventDefault();try{await call('/api/admin/employee',{id:u.id,employeeNumber:form.elements.employeeNumber.value});toast('Employee number verified');await refresh()}catch(err){form.querySelector('.errorBox').textContent=err.message}};
 };
 function render(){
  const q=search.value.trim().toLowerCase(),role=select.value;
  const filtered=users.filter(u=>(role==='all'||u.role===role)&&[u.name,u.username,u.employeeNumber||''].some(v=>String(v||'').toLowerCase().includes(q)));
  count.textContent=filtered.length+' of '+users.length+' users';
  area.replaceChildren();
  if(!filtered.length){area.append(empty('No matching accounts.'));return}
  for(const u of filtered){
   const card=el('article','lu-usercard');
   const info=el('div','lu-userinfo');info.append(el('strong',null,u.name||u.username),el('span','mut','@'+u.username+' · '+u.role+(u.grade?' · Grade '+u.grade:'')),el('small','mut',u.employeeNumber?'Employee #'+u.employeeNumber:'No verified employee number'));
   const actions=el('div','lu-useractions');
   if(u.role!=='admin'){
    actions.append(button('Reset password',()=>showReset(u),true));
    actions.append(button('Employee number',()=>editEmployee(u),true));
    actions.append(button(u.role==='teacher'?'Revoke teacher':'Approve teacher',async()=>{if(u.role==='student'&&!u.employeeNumber){editEmployee(u);return}if(!confirm((u.role==='teacher'?'Revoke teacher privileges from ':'Approve teacher privileges for ')+'@'+u.username+'?'))return;await call('/api/admin/role',{id:u.id,role:u.role==='teacher'?'student':'teacher'});await refresh()},true));
   }else actions.append(el('span','pill','Protected admin'));
   card.append(info,actions);area.append(card);
  }
 }
 search.oninput=render;select.onchange=render;render();
}
